* { box-sizing: border-box; }

body {
  margin: 0;
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  background: var(--bg);
  color: var(--text);
}

.dashboard {
  max-width: 960px;
  margin: 0 auto;
  padding: 32px 20px 64px;
}

.dashboard__header h1 {
  margin: 0 0 4px;
  font-size: 28px;
}

.dashboard__subtitle {
  margin: 0 0 24px;
  color: var(--muted);
}

.filter-form {
  display: flex;
  flex-wrap: wrap;
  gap: 16px;
  align-items: flex-end;
  background: var(--card);
  border: 1px solid var(--border);
  border-radius: 12px;
  padding: 16px;
  margin-bottom: 24px;
}

.filter-form__field {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.filter-form__field label {
  font-size: 13px;
  color: var(--muted);
}

.filter-form__field input {
  padding: 8px 10px;
  border: 1px solid var(--border);
  border-radius: 8px;
  font-size: 14px;
}

.filter-form__actions {
  display: flex;
  gap: 8px;
}

.btn {
  display: inline-block;
  padding: 9px 16px;
  border-radius: 8px;
  border: 1px solid transparent;
  font-size: 14px;
  cursor: pointer;
  text-decoration: none;
}

.btn--primary {
  background: var(--primary);
  color: #fff;
}

.btn--primary:hover { background: var(--primary-dark); }

.btn--ghost {
  background: transparent;
  color: var(--muted);
  border-color: var(--border);
}

.metrics {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
  gap: 16px;
  margin-bottom: 24px;
}

.metric-card {
  background: var(--card);
  border: 1px solid var(--border);
  border-radius: 12px;
  padding: 18px;
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.metric-card__label {
  font-size: 13px;
  color: var(--muted);
  text-transform: uppercase;
  letter-spacing: 0.04em;
}

.metric-card__value {
  font-size: 26px;
  font-weight: 700;
}

.panel {
  background: var(--card);
  border: 1px solid var(--border);
  border-radius: 12px;
  padding: 20px;
  margin-bottom: 24px;
}

.panel__title {
  margin: 0 0 16px;
  font-size: 18px;
}

.chart {
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.chart-bar {
  display: grid;
  grid-template-columns: 140px 1fr 120px;
  align-items: center;
  gap: 12px;
}

.chart-bar__label {
  font-size: 14px;
  color: var(--text);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.chart-bar__track {
  display: block;
  background: #eef2f7;
  border-radius: 6px;
  height: 22px;
  overflow: hidden;
}

.chart-bar__fill {
  display: block;
  height: 100%;
  background: linear-gradient(90deg, var(--primary), var(--accent));
  border-radius: 6px;
  min-width: 2px;
}

.chart-bar__value {
  font-size: 14px;
  text-align: right;
  color: var(--muted);
}

.orders-table {
  width: 100%;
  border-collapse: collapse;
  font-size: 14px;
}

.orders-table th,
.orders-table td {
  text-align: left;
  padding: 10px 12px;
  border-bottom: 1px solid var(--border);
}

.orders-table thead th {
  font-size: 12px;
  text-transform: uppercase;
  letter-spacing: 0.04em;
  color: var(--muted);
}

.orders-table__amount { text-align: right; }

.orders-table tfoot th {
  border-bottom: none;
  border-top: 2px solid var(--border);
}

.empty-state {
  background: var(--card);
  border: 1px dashed var(--border);
  border-radius: 12px;
  padding: 40px 20px;
  text-align: center;
}

.empty-state h2 {
  margin: 0 0 8px;
  font-size: 20px;
}

.empty-state p {
  margin: 0;
  color: var(--muted);
}
"}

